# Hindley-Milner birlestirme (unification) ve tip cikarimi -- kutuphanesiz.
# Terim:  ("deg", ad) | ("uygula", e1, e2) | ("lam", ad, govde)
sayac = [0]

def taze():
    sayac[0] += 1
    return ("dev", "t%d" % sayac[0])

def uygula_yer(t, s):
    if t[0] == "dev":
        return uygula_yer(s[t[1]], s) if t[1] in s else t
    if t[0] == "ok":
        return ("ok", uygula_yer(t[1], s), uygula_yer(t[2], s))
    return t

def icinde_var(v, t, s):
    t = uygula_yer(t, s)
    if t[0] == "dev":
        return t[1] == v
    if t[0] == "ok":
        return icinde_var(v, t[1], s) or icinde_var(v, t[2], s)
    return False

adim = [0]

def birlestir(a, b, s):
    adim[0] += 1
    a, b = uygula_yer(a, s), uygula_yer(b, s)
    if a == b:
        return s
    if a[0] == "dev":
        if icinde_var(a[1], b, s):
            raise TypeError("occurs check: " + a[1])
        s[a[1]] = b
        return s
    if b[0] == "dev":
        return birlestir(b, a, s)
    if a[0] == "ok" and b[0] == "ok":
        s = birlestir(a[1], b[1], s)
        return birlestir(a[2], b[2], s)
    raise TypeError("uyusmaz: %s / %s" % (a, b))

