# Ifade:  f(x) + (g(x) * f(x))     f ve g yan etkili: x'i degistiriyorlar.
class Durum:
    def __init__(self):
        self.x = 2
        self.iz = []
    def f(self):          # x'i 1 artirir, YENI x'i dondurur
        self.x += 1
        self.iz.append("f->%d" % self.x)
        return self.x
    def g(self):          # x'i 2 ile carpar, YENI x'i dondurur
        self.x *= 2
        self.iz.append("g->%d" % self.x)
        return self.x

