# KUCUK ADIM (small-step) anlambilim: her adimda TEK bir indirgeme yapilir.
# e ::= ("say", n) | ("+", e1, e2) | ("*", e1, e2)
def deger(e):
    return e[0] == "say"

def adim(e):
    """Bir tek indirgeme adimi uygular; hangi kuralin kullanildigini da dondurur."""
    if e[0] in ("+", "*"):
        if not deger(e[1]):
            e1, k = adim(e[1])
            return (e[0], e1, e[2]), "SOL-" + e[0]
        if not deger(e[2]):
            e2, k = adim(e[2])
            return (e[0], e[1], e2), "SAG-" + e[0]
        n = e[1][1] + e[2][1] if e[0] == "+" else e[1][1] * e[2][1]
        return ("say", n), "HESAP-" + e[0]
    raise ValueError(e)

def yaz(e):
    if e[0] == "say":
        return str(e[1])
    return "(" + yaz(e[1]) + " " + e[0] + " " + yaz(e[2]) + ")"

