# BUYUK ADIM (big-step / dogal) anlambilim: <c, s> ==> s'
# Turev agacini kurar, dugum sayisini ve yuksekligini olcer.
def ifade(e, s):
    if e[0] == "say":
        return e[1]
    if e[0] == "ad":
        return s[e[1]]
    a, b = ifade(e[1], s), ifade(e[2], s)
    return {"+": a + b, "-": a - b, "*": a * b, ">": int(a > b)}[e[0]]

def calis(c, s):
    """(yeni_durum, turev_agaci) dondurur. Agac: (kural, [alt agaclar])"""
    if c[0] == "atla":
        return s, ("ATLA", [])
    if c[0] == "ata":
        s2 = dict(s)
        s2[c[1]] = ifade(c[2], s)
        return s2, ("ATA", [])
    if c[0] == "sira":
        s1, t1 = calis(c[1], s)
        s2, t2 = calis(c[2], s1)
        return s2, ("SIRA", [t1, t2])
    if c[0] == "eger":
        if ifade(c[1], s):
            s2, t = calis(c[2], s)
            return s2, ("EGER-D", [t])
        s2, t = calis(c[3], s)
        return s2, ("EGER-Y", [t])
    if c[0] == "iken":
        if not ifade(c[1], s):
            return s, ("IKEN-Y", [])
        s1, t1 = calis(c[2], s)
        s2, t2 = calis(c, s1)          # ayni dongu, yeni durumda
        return s2, ("IKEN-D", [t1, t2])
    raise ValueError(c)

def dugum(t):
    return 1 + sum(dugum(a) for a in t[1])

def yukseklik(t):
    return 1 + max([yukseklik(a) for a in t[1]] or [0])

def kurallar(t, sayac):
    sayac[t[0]] = sayac.get(t[0], 0) + 1
    for a in t[1]:
        kurallar(a, sayac)
    return sayac

