# Kucuk bir Prolog: birlestirme (unification) + geri izleme (backtracking).
# Terim: ("atom", ad) | ("dev", ad) | ("yapi", ad, [argumanlar])
denemesi = [0]          # kac birlestirme denendi
cozum = [0]             # kac cozum bulundu

def coz(t, s):
    while t[0] == "dev" and t[1] in s:
        t = s[t[1]]
    return t

def birlestir(a, b, s):
    denemesi[0] += 1
    a, b = coz(a, s), coz(b, s)
    if a == b:
        return s
    if a[0] == "dev":
        s2 = dict(s); s2[a[1]] = b; return s2
    if b[0] == "dev":
        s2 = dict(s); s2[b[1]] = a; return s2
    if a[0] == "yapi" and b[0] == "yapi" and a[1] == b[1] and len(a[2]) == len(b[2]):
        for x, y in zip(a[2], b[2]):
            s = birlestir(x, y, s)
            if s is None:
                return None
        return s
    return None

sayac = [0]
def tazele(terim, harita):
    if terim[0] == "dev":
        if terim[1] not in harita:
            sayac[0] += 1
            harita[terim[1]] = ("dev", terim[1] + "#" + str(sayac[0]))
        return harita[terim[1]]
    if terim[0] == "yapi":
        return ("yapi", terim[1], [tazele(a, harita) for a in terim[2]])
    return terim

def kanitla(hedefler, s, kurallar):
    if not hedefler:
        cozum[0] += 1
        yield s
        return
    h, kalan = hedefler[0], hedefler[1:]
    for bas, govde in kurallar:
        harita = {}
        bas2 = tazele(bas, harita)
        govde2 = [tazele(g, harita) for g in govde]
        s2 = birlestir(h, bas2, dict(s))
        if s2 is not None:
            yield from kanitla(govde2 + kalan, s2, kurallar)

