# MiniDil: sozdizimi + TIP KURALLARI + ANLAMBILIM bir arada (donem sentezi).
# e ::= ("say",n) | ("dgr",b) | ("ad",x) | ("+",e1,e2) | ("<",e1,e2)
#     | ("eger",e1,e2,e3) | ("bagla",x,e1,e2) | ("fun",x,T,govde) | ("uygula",e1,e2)
# T ::= "Tam" | "Mant" | ("ok", T1, T2)

def tip(e, G):
    t = e[0]
    if t == "say":
        return "Tam"
    if t == "dgr":
        return "Mant"
    if t == "ad":
        if e[1] not in G:
            raise TypeError("tanimsiz ad: " + e[1])
        return G[e[1]]
    if t == "+":
        if tip(e[1], G) != "Tam" or tip(e[2], G) != "Tam":
            raise TypeError("+ icin Tam gerekir")
        return "Tam"
    if t == "<":
        if tip(e[1], G) != "Tam" or tip(e[2], G) != "Tam":
            raise TypeError("< icin Tam gerekir")
        return "Mant"
    if t == "eger":
        if tip(e[1], G) != "Mant":
            raise TypeError("kosul Mant olmali")
        t2, t3 = tip(e[2], G), tip(e[3], G)
        if t2 != t3:
            raise TypeError("dallar ayni tipte olmali: %s / %s" % (t2, t3))
        return t2
    if t == "bagla":
        G2 = dict(G)
        G2[e[1]] = tip(e[2], G)          # let: once e1'in tipi, sonra govde
        return tip(e[3], G2)
    if t == "fun":
        G2 = dict(G)
        G2[e[1]] = e[2]
        return ("ok", e[2], tip(e[3], G2))
    if t == "uygula":
        tf = tip(e[1], G)
        if not isinstance(tf, tuple) or tf[0] != "ok":
            raise TypeError("fonksiyon degil")
        if tip(e[2], G) != tf[1]:
            raise TypeError("arguman tipi uymuyor")
        return tf[2]
    raise ValueError(e)

def deg(e, C):
    t = e[0]
    if t == "say" or t == "dgr":
        return e[1]
    if t == "ad":
        return C[e[1]]
    if t == "+":
        return deg(e[1], C) + deg(e[2], C)
    if t == "<":
        return deg(e[1], C) < deg(e[2], C)
    if t == "eger":
        return deg(e[2], C) if deg(e[1], C) else deg(e[3], C)
    if t == "bagla":
        C2 = dict(C)
        C2[e[1]] = deg(e[2], C)
        return deg(e[3], C2)
    if t == "fun":
        return ("kapanis", e[1], e[3], dict(C))     # statik kapsam: cevreyi sakla
    if t == "uygula":
        k = deg(e[1], C)
        C2 = dict(k[3])
        C2[k[1]] = deg(e[2], C)
        return deg(k[2], C2)
    raise ValueError(e)

def yazT(T):
    return T if isinstance(T, str) else "(%s -> %s)" % (yazT(T[1]), yazT(T[2]))

